insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('promociones-y-descuentos-le-convienen-al-negocio','negocios',array['sociedad']::text[],'Promociones y descuentos: ¿le convienen al negocio?','Calcula cuánto debe aumentar la venta para que un descuento compense la rebaja del precio, y simula cuándo una promoción deja ganancia y cuándo pierde.','Simulación','~20 h',20,array['Descuentos','Promociones']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'economia marketing contabilidad administracion estadistica ingenieria industrial matematica ciencia de datos calculo de margenes. analisis de escenarios. simulacion. decision informada. hoja de calculo. un editor de graficos. datos inventados.',$a39sld${"id": "promociones-y-descuentos-le-convienen-al-negocio", "area": "negocios", "areas2": ["sociedad"], "titulo": "Promociones y descuentos: ¿le convienen al negocio?", "resumen": "Calcula cuánto debe aumentar la venta para que un descuento compense la rebaja del precio, y simula cuándo una promoción deja ganancia y cuándo pierde.", "tipo": "Simulación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Descuentos", "Promociones"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Marketing", "Contabilidad", "Administración", "Estadística", "Ingeniería Industrial", "Matemática", "Ciencia de Datos"], "problema": ["Un descuento atrae clientes, pero reduce lo que se gana por cada venta. Si no se vende lo suficiente más, el negocio termina ganando menos aunque venda más.", "Muchos negocios hacen promociones por costumbre sin calcular a partir de cuántas ventas extra valen la pena."], "desarrollar": ["Inventa un producto con precio, costo y margen, y calcula cuánto deben aumentar las ventas para que un descuento de diez, veinte y treinta por ciento deje la misma ganancia que antes.", "Simula distintos aumentos de venta posibles y señala en qué casos la promoción conviene, en cuáles no, y qué alternativas hay, como un paquete o un regalo en lugar de bajar el precio."], "ampliaciones": [{"titulo": "Descuentos por cantidad", "aporta": "analiza ofertas del tipo segunda unidad a mitad de precio."}, {"titulo": "Efecto en la imagen", "aporta": "reflexiona cómo los descuentos frecuentes cambian lo que el cliente espera pagar."}, {"titulo": "Promoción por tiempo limitado", "aporta": "evalúa si la urgencia aumenta las compras sin dañar el margen."}], "objetivos": ["Calcular el margen con descuento.", "Determinar las ventas necesarias.", "Simular escenarios.", "Proponer alternativas."], "habilidades": ["Cálculo de márgenes.", "Análisis de escenarios.", "Simulación.", "Decisión informada."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Datos inventados."], "lineamientos": ["Usa productos y precios inventados; no presentes el resultado como regla para todos los negocios.", "Evita proponer descuentos engañosos, como subir el precio antes de rebajarlo."], "otroSector": "El mismo análisis sirve para evaluar becas, cuotas reducidas, ofertas de lanzamiento o tarifas promocionales."}$a39sld$::jsonb,47),
('disena-una-oferta-atractiva-sin-sacrificar-ganancias','negocios',array['sociedad']::text[],'Diseña una oferta atractiva sin sacrificar ganancias','Diseña una oferta que le parezca atractiva al cliente, como un combo, un paquete o un beneficio extra, y verifica con números que el negocio igual gane.','Plan','~18 h',18,array['Ofertas','Márgenes']::text[],array['crear','resolver']::text[],'ficticios',NULL,'marketing economia administracion contabilidad ingenieria industrial comunicaciones estadistica psicologia diseno de ofertas. calculo de margenes. pensamiento creativo. analisis comparativo. hoja de calculo. un editor de diseno sencillo. datos inventados.',$a40sld${"id": "disena-una-oferta-atractiva-sin-sacrificar-ganancias", "area": "negocios", "areas2": ["sociedad"], "titulo": "Diseña una oferta atractiva sin sacrificar ganancias", "resumen": "Diseña una oferta que le parezca atractiva al cliente, como un combo, un paquete o un beneficio extra, y verifica con números que el negocio igual gane.", "tipo": "Plan", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Ofertas", "Márgenes"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Marketing", "Economía", "Administración", "Contabilidad", "Ingeniería Industrial", "Comunicaciones", "Estadística", "Psicología"], "problema": ["Una buena oferta no es solo bajar el precio: puede combinar productos, agregar un beneficio de bajo costo o dar más valor sin regalar el margen.", "El reto es que el cliente sienta que gana y que el negocio no pierda."], "desarrollar": ["Para un negocio inventado, diseña tres ofertas distintas, por ejemplo un combo, un paquete familiar y un beneficio extra de bajo costo, y calcula el costo y el margen de cada una.", "Compara cuál resulta más atractiva y cuál deja más ganancia, y elige la mejor combinación explicando el equilibrio entre ambas."], "ampliaciones": [{"titulo": "Lo que valora el cliente", "aporta": "pregunta a cinco personas qué oferta les parecería mejor."}, {"titulo": "Ofertas por temporada", "aporta": "diseña ofertas distintas para días de más y de menos demanda."}, {"titulo": "Oferta para clientes frecuentes", "aporta": "adapta la oferta para quienes compran con regularidad."}], "objetivos": ["Diseñar ofertas con valor percibido.", "Calcular márgenes por oferta.", "Comparar atractivo y ganancia.", "Elegir con criterio."], "habilidades": ["Diseño de ofertas.", "Cálculo de márgenes.", "Pensamiento creativo.", "Análisis comparativo."], "herramientas": ["Hoja de cálculo.", "Un editor de diseño sencillo.", "Datos inventados."], "lineamientos": ["Usa un negocio inventado y asegúrate de que las ofertas sean claras y honestas, sin letras chicas engañosas.", "No sacrifiques calidad ni seguridad para mejorar el margen."], "otroSector": "El mismo ejercicio sirve para diseñar paquetes de servicios, planes de suscripción o entradas con beneficios para un evento."}$a40sld$::jsonb,48),
('programas-de-fidelizacion-de-clientes','negocios',array['sociedad','tecnologia']::text[],'Programas de fidelización de clientes','Diseña un programa para que los clientes vuelvan, como puntos, tarjetas o beneficios, y calcula si el costo del programa se compensa con las ventas que genera.','Plan','~20 h',20,array['Fidelización','Clientes']::text[],array['crear','resolver']::text[],'ficticios',NULL,'marketing administracion psicologia economia ingenieria de sistemas comunicaciones estadistica ciencia de datos diseno de programas. estimacion de costos y retorno. analisis de escenarios. pensamiento centrado en el cliente. hoja de calculo. un editor de diseno sencillo. datos inventados.',$a41sld${"id": "programas-de-fidelizacion-de-clientes", "area": "negocios", "areas2": ["sociedad", "tecnologia"], "titulo": "Programas de fidelización de clientes", "resumen": "Diseña un programa para que los clientes vuelvan, como puntos, tarjetas o beneficios, y calcula si el costo del programa se compensa con las ventas que genera.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Fidelización", "Clientes"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Marketing", "Administración", "Psicología", "Economía", "Ingeniería de Sistemas", "Comunicaciones", "Estadística", "Ciencia de Datos"], "problema": ["Conseguir un cliente nuevo cuesta más que mantener uno que ya compró. Por eso muchos negocios usan tarjetas de sellos, puntos o descuentos para quienes regresan.", "Pero un programa mal diseñado puede costar más de lo que deja, o no cambiar el comportamiento de nadie."], "desarrollar": ["Para un negocio inventado, diseña dos programas de fidelización distintos, con reglas claras sobre cómo se gana y cómo se canjea el beneficio, y estima su costo por cliente.", "Supón cuántos clientes volverían más seguido y cuánto más gastarían, calcula el efecto sobre la ganancia y elige el programa más conveniente con sus riesgos."], "ampliaciones": [{"titulo": "Costo del beneficio", "aporta": "calcula el costo real de cada recompensa para el negocio."}, {"titulo": "Versión digital", "aporta": "propone cómo funcionaría el programa con un código o una aplicación sencilla."}, {"titulo": "Qué hacer con quienes no vuelven", "aporta": "diseña un mensaje para reactivar a clientes inactivos."}], "objetivos": ["Diseñar reglas claras de beneficios.", "Estimar el costo del programa.", "Calcular el efecto sobre las ventas.", "Comparar alternativas."], "habilidades": ["Diseño de programas.", "Estimación de costos y retorno.", "Análisis de escenarios.", "Pensamiento centrado en el cliente."], "herramientas": ["Hoja de cálculo.", "Un editor de diseño sencillo.", "Datos inventados."], "lineamientos": ["Usa un negocio inventado y evita pedir datos personales innecesarios a los clientes en tu diseño.", "Si propones un programa digital, considera la protección de los datos de los clientes."], "otroSector": "El mismo concepto sirve para premiar a voluntarios, a usuarios activos de una aplicación o a socios de una organización."}$a41sld$::jsonb,49),
('comparando-modelos-y-estrategias-de-venta-de-distintos-negocios','negocios',array['sociedad']::text[],'Comparando modelos y estrategias de venta de distintos negocios','Compara cómo ganan dinero tres negocios de distinto tipo, como una tienda, una suscripción y un servicio por encargo, y qué ventajas y riesgos tiene cada modelo.','Análisis','~22 h',22,array['Modelos de negocio','Comparación']::text[],array['investigar']::text[],'publicos',NULL,'administracion marketing economia ingenieria industrial contabilidad comunicaciones sociologia ingenieria de sistemas analisis de modelos de negocio. busqueda de informacion. analisis comparativo. argumentacion. una tabla comparativa. informes y paginas publicas de empresas. un editor de presentaciones.',$a42sld${"id": "comparando-modelos-y-estrategias-de-venta-de-distintos-negocios", "area": "negocios", "areas2": ["sociedad"], "titulo": "Comparando modelos y estrategias de venta de distintos negocios", "resumen": "Compara cómo ganan dinero tres negocios de distinto tipo, como una tienda, una suscripción y un servicio por encargo, y qué ventajas y riesgos tiene cada modelo.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Modelos de negocio", "Comparación"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Administración", "Marketing", "Economía", "Ingeniería Industrial", "Contabilidad", "Comunicaciones", "Sociología", "Ingeniería de Sistemas"], "problema": ["No todos los negocios ganan dinero de la misma manera: algunos venden productos, otros cobran por uso, otros por suscripción o por comisión. Cada modelo tiene sus costos, sus riesgos y su manera de crecer.", "Compararlos ayuda a entender por qué ciertos negocios se parecen y por qué algunos resultan más estables que otros."], "desarrollar": ["Elige tres negocios conocidos de distinto modelo y, con información pública, describe cómo generan ingresos, cuáles son sus costos principales y qué clientes atienden.", "Arma una tabla comparativa, identifica las ventajas y riesgos de cada modelo y concluye cuál sería más fácil de iniciar con poco capital y por qué."], "ampliaciones": [{"titulo": "Modelo mixto", "aporta": "propón cómo un negocio podría combinar dos modelos."}, {"titulo": "Un cambio de modelo", "aporta": "analiza un caso en que un negocio cambió su forma de cobrar."}, {"titulo": "Aplicarlo a tu idea", "aporta": "elige el modelo más adecuado para una idea tuya."}], "objetivos": ["Reconocer distintos modelos de ingreso.", "Comparar con información pública.", "Evaluar ventajas y riesgos.", "Aplicar el análisis a una idea."], "habilidades": ["Análisis de modelos de negocio.", "Búsqueda de información.", "Análisis comparativo.", "Argumentación."], "herramientas": ["Una tabla comparativa.", "Informes y páginas públicas de empresas.", "Un editor de presentaciones."], "lineamientos": ["Usa solo información pública y cita las fuentes; no ataques ni elogies a empresas concretas sin sustento.", "Aclara que un análisis externo no conoce los datos internos de los negocios."], "otroSector": "La misma comparación sirve para estudiar cómo se financian organizaciones, medios de comunicación o aplicaciones."}$a42sld$::jsonb,50),
('compras-en-grupo-y-gastos-compartidos-cuanto-se-ahorra','negocios',array['sociedad','tecnologia']::text[],'Compras en grupo y gastos compartidos: ¿cuánto se ahorra?','Calcula cuánto dinero puede ahorrarse un grupo comprando o pagando en común, como servicios compartidos o compras por mayor, y qué reglas hacen que funcione.','Análisis','~18 h',18,array['Compras en grupo','Gastos compartidos']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'economia administracion contabilidad ingenieria industrial sociologia estadistica ingenieria de sistemas trabajo social calculo de ahorro. diseno de reglas. organizacion de cuentas. negociacion. hoja de calculo. un editor de graficos. casos inventados.',$a43sld${"id": "compras-en-grupo-y-gastos-compartidos-cuanto-se-ahorra", "area": "negocios", "areas2": ["sociedad", "tecnologia"], "titulo": "Compras en grupo y gastos compartidos: ¿cuánto se ahorra?", "resumen": "Calcula cuánto dinero puede ahorrarse un grupo comprando o pagando en común, como servicios compartidos o compras por mayor, y qué reglas hacen que funcione.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Compras en grupo", "Gastos compartidos"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Administración", "Contabilidad", "Ingeniería Industrial", "Sociología", "Estadística", "Ingeniería de Sistemas", "Trabajo Social"], "problema": ["Comprar entre varios suele salir más barato: se consigue precio por volumen, se dividen costos fijos y se evita el desperdicio. Pero también aparecen problemas, como quién adelanta el dinero o quién usa más.", "Sin reglas claras, los acuerdos informales terminan en malestar."], "desarrollar": ["Inventa tres situaciones, como compartir una suscripción, comprar alimentos por mayor entre varios hogares o dividir el alquiler de un equipo, y calcula el ahorro frente a comprar individualmente.", "Identifica los riesgos de cada una y propón reglas simples, como quién administra, cómo se paga y qué se hace si alguien deja el grupo."], "ampliaciones": [{"titulo": "Cuánta gente es ideal", "aporta": "calcula cuántas personas conviene reunir antes de que el ahorro deje de crecer."}, {"titulo": "Registro de gastos", "aporta": "diseña una hoja para llevar cuentas claras del grupo."}, {"titulo": "Cuando alguien no cumple", "aporta": "propón reglas para resolver los desacuerdos."}], "objetivos": ["Calcular ahorros por compra colectiva.", "Identificar riesgos del acuerdo.", "Proponer reglas claras.", "Diseñar un registro simple."], "habilidades": ["Cálculo de ahorro.", "Diseño de reglas.", "Organización de cuentas.", "Negociación."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Casos inventados."], "lineamientos": ["Usa casos inventados y no incluyas datos reales de personas ni de sus cuentas.", "Revisa las condiciones de uso de los servicios antes de proponer compartirlos, pues algunos lo prohíben."], "otroSector": "El mismo análisis sirve para compras compartidas entre negocios pequeños, organizaciones o comunidades."}$a43sld$::jsonb,51),
('modelo-economico-de-una-cooperativa-estudiantil','negocios',array['sociedad','educacion']::text[],'Modelo económico de una cooperativa estudiantil','Diseña cómo funcionaría una cooperativa estudiantil que vende productos o servicios: quién aporta, cómo se decide, cuánto se gana y cómo se reparte.','Plan','3 a 5 semanas',25,array['Cooperativa','Economía solidaria']::text[],array['crear']::text[],'ficticios',NULL,'economia administracion contabilidad sociologia trabajo social derecho ingenieria industrial educacion modelado economico. diseno organizacional. simulacion en hoja de calculo. trabajo en equipo. hoja de calculo. un editor de documentos. un editor de presentaciones.',$a44sld${"id": "modelo-economico-de-una-cooperativa-estudiantil", "area": "negocios", "areas2": ["sociedad", "educacion"], "titulo": "Modelo económico de una cooperativa estudiantil", "resumen": "Diseña cómo funcionaría una cooperativa estudiantil que vende productos o servicios: quién aporta, cómo se decide, cuánto se gana y cómo se reparte.", "tipo": "Plan", "tiempo": "3 a 5 semanas", "horas": 25, "etiquetas": ["Cooperativa", "Economía solidaria"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Administración", "Contabilidad", "Sociología", "Trabajo Social", "Derecho", "Ingeniería Industrial", "Educación"], "problema": ["Una cooperativa es un negocio donde las personas que participan son también sus dueñas. Para estudiantes puede ser una forma de vender útiles, comida o servicios y reinvertir lo que se gana.", "Pero necesita reglas claras de aportes, decisiones y reparto, y números que muestren si es sostenible."], "desarrollar": ["Inventa una cooperativa de estudiantes con un producto o servicio, define cuánto aporta cada socio, qué costos tiene y cuánto vende por mes, y calcula su resultado económico.", "Diseña las reglas de decisión y de reparto de excedentes, simula tres meses y señala qué problemas podrían aparecer y cómo se resolverían."], "ampliaciones": [{"titulo": "Reparto del excedente", "aporta": "compara repartir todo, reinvertir parte o dejar un fondo común."}, {"titulo": "Distintos niveles de aporte", "aporta": "analiza qué pasa si los socios aportan montos o tiempos distintos."}, {"titulo": "Estatutos básicos", "aporta": "redacta un reglamento simple de la cooperativa."}], "objetivos": ["Comprender cómo funciona una cooperativa.", "Calcular su resultado económico.", "Diseñar reglas de decisión y reparto.", "Simular y evaluar riesgos."], "habilidades": ["Modelado económico.", "Diseño organizacional.", "Simulación en hoja de cálculo.", "Trabajo en equipo."], "herramientas": ["Hoja de cálculo.", "Un editor de documentos.", "Un editor de presentaciones."], "lineamientos": ["Trabaja con un caso inventado; si luego quieres formar una cooperativa real, consulta la normativa y a un asesor, pues exige trámites propios.", "No presentes el modelo como un acuerdo legal."], "otroSector": "El mismo modelo sirve para organizaciones de vecinos, asociaciones de productores o clubes con fines económicos."}$a44sld$::jsonb,52),
('como-repartir-costos-y-beneficios-de-una-compra-colectiva-de-for','negocios',array['sociedad','derecho']::text[],'¿Cómo repartir costos y beneficios de una compra colectiva de forma justa?','Compara distintas formas de repartir costos y beneficios en un grupo, como por partes iguales, por uso o por capacidad de pago, y qué considera justa la gente en cada caso.','Investigación','~20 h',20,array['Reparto','Justicia']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'economia matematica sociologia derecho administracion psicologia contabilidad filosofia calculo de repartos. analisis de criterios de justicia. encuestas breves. argumentacion. hoja de calculo. un formulario anonimo. casos inventados.',$a45sld${"id": "como-repartir-costos-y-beneficios-de-una-compra-colectiva-de-for", "area": "negocios", "areas2": ["sociedad", "derecho"], "titulo": "¿Cómo repartir costos y beneficios de una compra colectiva de forma justa?", "resumen": "Compara distintas formas de repartir costos y beneficios en un grupo, como por partes iguales, por uso o por capacidad de pago, y qué considera justa la gente en cada caso.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Reparto", "Justicia"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Matemática", "Sociología", "Derecho", "Administración", "Psicología", "Contabilidad", "Filosofía"], "problema": ["Cuando varias personas comparten un gasto, no siempre es evidente cómo dividirlo. Repartir en partes iguales es simple, pero puede resultar injusto si alguien usa más o gana menos.", "Lo que se considera justo depende de lo que se valore, como la igualdad, el uso o la necesidad, y por eso es un buen tema para analizar con casos concretos."], "desarrollar": ["Inventa tres situaciones de gasto compartido, como un viaje, un servicio o una compra grande, y calcula el reparto con tres reglas distintas: partes iguales, por uso y por capacidad de pago.", "Compara los resultados, pregunta a un grupo pequeño cuál regla les parece más justa en cada caso y analiza por qué las opiniones difieren."], "ampliaciones": [{"titulo": "Reglas mixtas", "aporta": "diseña una regla que combine dos criterios."}, {"titulo": "Un modelo simple de decisión", "aporta": "propone cómo un grupo podría elegir su regla de manera democrática."}, {"titulo": "Casos reales de la comunidad", "aporta": "analiza cómo se reparten costos en una junta de vecinos o una asociación."}], "objetivos": ["Aplicar distintas reglas de reparto.", "Comparar resultados.", "Recoger opiniones sobre justicia.", "Argumentar una propuesta."], "habilidades": ["Cálculo de repartos.", "Análisis de criterios de justicia.", "Encuestas breves.", "Argumentación."], "herramientas": ["Hoja de cálculo.", "Un formulario anónimo.", "Casos inventados."], "lineamientos": ["Usa casos inventados y consulta opiniones de forma anónima y voluntaria, sin forzar a nadie a revelar sus ingresos.", "No presentes una regla como la única justa: depende de los valores del grupo."], "otroSector": "El mismo análisis sirve para repartir tareas, cuotas de una organización o beneficios de un proyecto comunitario."}$a45sld$::jsonb,53),
('es-viable-economicamente-tu-idea','negocios',array['sociedad']::text[],'¿Es viable económicamente tu idea?','Evalúa si una idea de proyecto o negocio se sostendría económicamente, revisando cuánto cuesta, cuánto ingresaría, qué riesgos tiene y qué haría falta para que funcione.','Análisis','~22 h',22,array['Viabilidad','Evaluación']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'economia administracion contabilidad ingenieria industrial finanzas estadistica ingenieria de sistemas marketing analisis de viabilidad. modelado financiero basico. analisis de riesgos. comunicacion de conclusiones. hoja de calculo. un editor de presentaciones. datos inventados o estimados.',$a46sld${"id": "es-viable-economicamente-tu-idea", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Es viable económicamente tu idea?", "resumen": "Evalúa si una idea de proyecto o negocio se sostendría económicamente, revisando cuánto cuesta, cuánto ingresaría, qué riesgos tiene y qué haría falta para que funcione.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Viabilidad", "Evaluación"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Administración", "Contabilidad", "Ingeniería Industrial", "Finanzas", "Estadística", "Ingeniería de Sistemas", "Marketing"], "problema": ["Una idea puede ser buena y aun así no ser viable si los costos superan lo que puede ingresar o si depende de condiciones difíciles de lograr. Evaluar la viabilidad antes de empezar evita perder tiempo y dinero.", "No se trata de decir si la idea es buena o mala, sino de entender qué tendría que cumplirse para que funcione."], "desarrollar": ["Elige una idea tuya o inventada y evalúa sus partes principales: demanda esperada, costos de arranque y de operación, ingresos posibles y riesgos que podrían afectarla.", "Arma un escenario normal, uno optimista y uno pesimista, y concluye si la idea es viable, qué condiciones necesita y cuáles serían los primeros pasos para probarla con poco riesgo."], "ampliaciones": [{"titulo": "Lista de supuestos", "aporta": "identifica los supuestos más frágiles y cómo comprobarlos."}, {"titulo": "Factores que no son dinero", "aporta": "añade tiempo, esfuerzo del equipo y valor social."}, {"titulo": "Comparar dos ideas", "aporta": "evalúa dos ideas con los mismos criterios y elige una."}], "objetivos": ["Evaluar costos, ingresos y riesgos.", "Construir escenarios.", "Identificar supuestos críticos.", "Concluir con criterio."], "habilidades": ["Análisis de viabilidad.", "Modelado financiero básico.", "Análisis de riesgos.", "Comunicación de conclusiones."], "herramientas": ["Hoja de cálculo.", "Un editor de presentaciones.", "Datos inventados o estimados."], "lineamientos": ["Usa una idea propia o inventada y marca claramente las estimaciones; no inviertas dinero real solo por este análisis.", "Si la idea involucra a otras personas, pide su opinión sin comprometer datos privados."], "otroSector": "El mismo análisis sirve para evaluar un proyecto social, una app, un evento o una propuesta de investigación."}$a46sld$::jsonb,54),
('plan-financiero-y-simulacion-de-un-proyecto-ficticio','negocios',array['educacion']::text[],'Plan financiero y simulación de un proyecto ficticio','Construye el plan financiero completo de un proyecto o negocio ficticio, con inversión, ingresos, costos, flujo de caja y escenarios, y simula varios meses.','Simulación','4 a 6 semanas',30,array['Plan financiero','Simulación']::text[],array['crear','investigar']::text[],'ficticios',NULL,'finanzas contabilidad economia administracion ingenieria industrial estadistica ingenieria de sistemas matematica modelado financiero. flujo de caja. simulacion en hoja de calculo. presentacion de informes. hoja de calculo. un editor de graficos. un editor de presentaciones.',$a47sld${"id": "plan-financiero-y-simulacion-de-un-proyecto-ficticio", "area": "negocios", "areas2": ["educacion"], "titulo": "Plan financiero y simulación de un proyecto ficticio", "resumen": "Construye el plan financiero completo de un proyecto o negocio ficticio, con inversión, ingresos, costos, flujo de caja y escenarios, y simula varios meses.", "tipo": "Simulación", "tiempo": "4 a 6 semanas", "horas": 30, "etiquetas": ["Plan financiero", "Simulación"], "intencion": ["crear", "investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Finanzas", "Contabilidad", "Economía", "Administración", "Ingeniería Industrial", "Estadística", "Ingeniería de Sistemas", "Matemática"], "problema": ["Un plan financiero ordena en números lo que un proyecto necesita y lo que podría generar. Sin él es difícil saber cuándo habrá dinero, cuándo faltará y cuánto se necesita para empezar.", "Practicar con un caso ficticio permite aprender las partes de un plan sin arriesgar dinero real."], "desarrollar": ["Inventa un proyecto con una inversión inicial, define los ingresos y costos mensuales durante un año, y arma un flujo de caja que muestre mes a mes cuánto dinero entra, sale y queda.", "Simula un escenario normal y otro con ventas menores, señala en qué meses faltaría dinero y qué decisiones tomarías, y resume en una hoja de resultados."], "ampliaciones": [{"titulo": "Cuándo se recupera la inversión", "aporta": "calcula en qué mes el proyecto recupera lo invertido."}, {"titulo": "Fuentes de financiamiento", "aporta": "compara usar ahorros propios, un socio o un préstamo ficticio."}, {"titulo": "Informe para un inversionista", "aporta": "prepara un resumen de una página del plan."}], "objetivos": ["Estructurar un plan financiero.", "Construir un flujo de caja.", "Simular escenarios.", "Comunicar resultados."], "habilidades": ["Modelado financiero.", "Flujo de caja.", "Simulación en hoja de cálculo.", "Presentación de informes."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Un editor de presentaciones."], "lineamientos": ["Usa un proyecto ficticio y datos inventados; no uses información financiera real de personas ni empresas.", "Aclara que es un ejercicio y no una asesoría, y que un plan real necesita validación profesional."], "otroSector": "El mismo plan sirve para organizar el presupuesto de un evento, de una organización estudiantil o de una investigación."}$a47sld$::jsonb,55),
('quien-se-queda-con-el-dinero-entre-la-chacra-y-tu-mesa','negocios',array['agricultura','sociedad']::text[],'¿Quién se queda con el dinero entre la chacra y tu mesa?','Sigue el recorrido de un alimento desde quien lo produce hasta quien lo consume y calcula cuánto del precio final se queda cada participante de la cadena.','Análisis','~22 h',22,array['Cadena de valor','Alimentos']::text[],array['investigar']::text[],'publicos',NULL,'economia ingenieria agroindustrial administracion sociologia estadistica contabilidad geografia ingenieria industrial analisis de cadenas de valor. busqueda de datos publicos. calculo de margenes. visualizacion. hoja de calculo. reportes de precios del estado y de mercados mayoristas. un editor de graficos.',$a48sld${"id": "quien-se-queda-con-el-dinero-entre-la-chacra-y-tu-mesa", "area": "negocios", "areas2": ["agricultura", "sociedad"], "titulo": "¿Quién se queda con el dinero entre la chacra y tu mesa?", "resumen": "Sigue el recorrido de un alimento desde quien lo produce hasta quien lo consume y calcula cuánto del precio final se queda cada participante de la cadena.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Cadena de valor", "Alimentos"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Ingeniería Agroindustrial", "Administración", "Sociología", "Estadística", "Contabilidad", "Geografía", "Ingeniería Industrial"], "problema": ["El precio que se paga por un alimento en el mercado no es el que recibe quien lo cultivó. En el camino participan transportistas, mayoristas, minoristas y otros, y cada uno cobra por su trabajo y su riesgo.", "A veces el productor recibe muy poco y el consumidor paga mucho, y es difícil saber dónde se concentra la diferencia."], "desarrollar": ["Elige un alimento común y, con información pública de precios en chacra, mayorista y minorista, reconstruye su cadena y calcula qué proporción del precio final corresponde a cada etapa.", "Presenta el resultado en un gráfico, analiza qué etapas aportan más valor o más costo, y reflexiona sobre qué cambios podrían hacer la cadena más justa o más eficiente."], "ampliaciones": [{"titulo": "Productos distintos", "aporta": "compara la cadena de dos alimentos, uno fresco y uno procesado."}, {"titulo": "Venta directa", "aporta": "calcula qué cambiaría si el productor vendiera directo al consumidor."}, {"titulo": "Evolución de precios", "aporta": "estudia cómo varían los márgenes en el tiempo."}], "objetivos": ["Reconstruir una cadena de valor.", "Calcular la distribución del precio.", "Analizar costos de cada etapa.", "Reflexionar sobre mejoras posibles."], "habilidades": ["Análisis de cadenas de valor.", "Búsqueda de datos públicos.", "Cálculo de márgenes.", "Visualización."], "herramientas": ["Hoja de cálculo.", "Reportes de precios del Estado y de mercados mayoristas.", "Un editor de gráficos."], "lineamientos": ["Usa precios públicos con su fecha y evita culpar a un grupo de la cadena: cada etapa tiene costos reales.", "Aclara que los márgenes varían según el lugar y la temporada."], "otroSector": "La misma lógica sirve para analizar cadenas de otros productos, como ropa, tecnología o materiales de construcción."}$a48sld$::jsonb,56),
('si-es-gratis-quien-paga-la-economia-de-las-apps-gratuitas','negocios',array['tecnologia','derecho']::text[],'Si es gratis, ¿quién paga? La economía de las apps gratuitas','Investiga cómo ganan dinero las aplicaciones y servicios gratuitos, mediante publicidad, datos, versiones pagadas o alianzas, y qué implica eso para quien los usa.','Investigación','~20 h',20,array['Modelos gratuitos','Datos']::text[],array['investigar']::text[],'publicos',NULL,'economia ingenieria de sistemas administracion derecho marketing comunicaciones ciencia de datos sociologia analisis de modelos de negocio. lectura critica de terminos de uso. investigacion en fuentes publicas. comunicacion clara. una tabla comparativa. terminos de uso y reportes publicos. un editor de presentaciones.',$a49sld${"id": "si-es-gratis-quien-paga-la-economia-de-las-apps-gratuitas", "area": "negocios", "areas2": ["tecnologia", "derecho"], "titulo": "Si es gratis, ¿quién paga? La economía de las apps gratuitas", "resumen": "Investiga cómo ganan dinero las aplicaciones y servicios gratuitos, mediante publicidad, datos, versiones pagadas o alianzas, y qué implica eso para quien los usa.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Modelos gratuitos", "Datos"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Ingeniería de Sistemas", "Administración", "Derecho", "Marketing", "Comunicaciones", "Ciencia de Datos", "Sociología"], "problema": ["Muchas aplicaciones no cobran, pero sus empresas ganan millones. Los ingresos pueden venir de anuncios, de planes pagados, de comisiones o de usar la información de los usuarios, y no siempre se explica con claridad.", "Entender cómo funciona ese modelo ayuda a usar los servicios con criterio y a diseñar los propios."], "desarrollar": ["Elige cuatro aplicaciones gratuitas de uso común y, con información pública, como sus términos de uso y reportes, identifica de dónde obtiene dinero cada una.", "Clasifica los modelos, compara qué le cuesta al usuario aunque no pague en dinero, como atención o datos, y escribe una guía corta de preguntas que conviene hacerse antes de usar un servicio gratuito."], "ampliaciones": [{"titulo": "Tu propio uso", "aporta": "estima cuánto tiempo y datos propios entregas a una aplicación."}, {"titulo": "Modelo para una app propia", "aporta": "diseña cómo ganaría dinero una aplicación estudiantil sin depender de los datos."}, {"titulo": "Cambios de modelo", "aporta": "estudia una app que pasó de gratuita a pagada y qué ocurrió."}], "objetivos": ["Identificar modelos de ingreso.", "Leer información pública con criterio.", "Reconocer costos no monetarios.", "Formular preguntas de uso responsable."], "habilidades": ["Análisis de modelos de negocio.", "Lectura crítica de términos de uso.", "Investigación en fuentes públicas.", "Comunicación clara."], "herramientas": ["Una tabla comparativa.", "Términos de uso y reportes públicos.", "Un editor de presentaciones."], "lineamientos": ["Usa solo información pública y no afirmes prácticas que no puedas sustentar con fuentes.", "No incluyas tus datos personales ni los de otros en el análisis."], "otroSector": "El mismo análisis sirve para entender cómo se financian medios, plataformas educativas o servicios públicos."}$a49sld$::jsonb,57),
('cuanto-cuesta-formalizar-un-negocio-pequeno-y-que-tramites-exige','negocios',array['derecho','sociedad']::text[],'¿Cuánto cuesta formalizar un negocio pequeño y qué trámites exige?','Investiga qué pasos, plazos y costos implica formalizar un negocio pequeño en tu país, y compara qué se gana y qué se paga al ser formal frente a informal.','Guía','~20 h',20,array['Formalización','Trámites']::text[],array['investigar','resolver']::text[],'publicos',NULL,'derecho administracion contabilidad economia ingenieria industrial ciencias politicas comunicaciones ingenieria de sistemas busqueda en fuentes oficiales. organizacion de procesos. analisis de costos. redaccion clara. portales oficiales. hoja de calculo. un editor de esquemas.',$a50sld${"id": "cuanto-cuesta-formalizar-un-negocio-pequeno-y-que-tramites-exige", "area": "negocios", "areas2": ["derecho", "sociedad"], "titulo": "¿Cuánto cuesta formalizar un negocio pequeño y qué trámites exige?", "resumen": "Investiga qué pasos, plazos y costos implica formalizar un negocio pequeño en tu país, y compara qué se gana y qué se paga al ser formal frente a informal.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Formalización", "Trámites"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Contabilidad", "Economía", "Ingeniería Industrial", "Ciencias Políticas", "Comunicaciones", "Ingeniería de Sistemas"], "problema": ["Muchos negocios pequeños funcionan sin registro porque formalizarse parece complicado y caro. Pero la formalidad también da acceso a crédito, contratos, comprobantes y protección.", "La información oficial suele estar dispersa, y entenderla ayuda a decidir con calma."], "desarrollar": ["Con información de páginas oficiales, arma una guía paso a paso de cómo formalizar un negocio de un solo dueño, indicando trámites, instituciones, costos, tiempos y obligaciones tributarias básicas.", "Compara de forma sencilla qué costos y beneficios tendría ser formal para un negocio pequeño inventado, y presenta una lista de preguntas para resolver con un profesional."], "ampliaciones": [{"titulo": "Régimen y costos", "aporta": "compara las opciones de régimen tributario disponibles."}, {"titulo": "Barreras percibidas", "aporta": "entrevista a dos emprendedores sobre por qué postergan la formalización."}, {"titulo": "Guía visual", "aporta": "convierte los pasos en un esquema fácil de seguir."}], "objetivos": ["Investigar trámites oficiales.", "Organizar la información paso a paso.", "Comparar costos y beneficios.", "Explicar con claridad."], "habilidades": ["Búsqueda en fuentes oficiales.", "Organización de procesos.", "Análisis de costos.", "Redacción clara."], "herramientas": ["Portales oficiales.", "Hoja de cálculo.", "Un editor de esquemas."], "lineamientos": ["Usa solo fuentes oficiales y fecha tu información, porque las normas cambian con frecuencia.", "Aclara que es una guía informativa y no asesoría legal ni tributaria."], "otroSector": "La misma guía sirve para trámites de otras actividades, como registrar una asociación, una marca o un proyecto."}$a50sld$::jsonb,58)
